import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const TOTAL = 1200;
  const CORE_COUNT = 90;
  const FIELD_COUNT = TOTAL - CORE_COUNT;

  const corePositions = [];
  const fieldPositions = [];
  const corePhases = [];
  const fieldPhases = [];
  const coreDirections = [];
  const fieldDirections = [];

  const ellipsoidSize = new THREE.Vector3(6, 4, 5);
  const ellipsoidCenter = new THREE.Vector3(0, 0, -1.5);
  const coreRadius = 0.5;
  const particleRadius = 0.012;

  function randomInEllipsoid() {
    const u = Math.random();
    const v = Math.random();
    const theta = u * 2 * Math.PI;
    const phi = Math.acos(2 * v - 1);
    const r = Math.cbrt(Math.random());
    const x = r * Math.sin(phi) * Math.cos(theta);
    const y = r * Math.sin(phi) * Math.sin(theta);
    const z = r * Math.cos(phi);
    return new THREE.Vector3(
      x * ellipsoidSize.x * 0.5,
      y * ellipsoidSize.y * 0.5,
      z * ellipsoidSize.z * 0.5
    ).add(ellipsoidCenter);
  }

  function randomInSphere(radius) {
    const u = Math.random();
    const v = Math.random();
    const theta = u * 2 * Math.PI;
    const phi = Math.acos(2 * v - 1);
    const r = Math.cbrt(Math.random()) * radius;
    return new THREE.Vector3(
      r * Math.sin(phi) * Math.cos(theta),
      r * Math.sin(phi) * Math.sin(theta),
      r * Math.cos(phi)
    );
  }

  // Core particles
  for (let i = 0; i < CORE_COUNT; i++) {
    const pos = randomInSphere(coreRadius);
    corePositions.push(pos);
    corePhases.push(Math.random() * Math.PI * 2);
    coreDirections.push(
      new THREE.Vector3(
        (Math.random() - 0.5) * 0.08,
        (Math.random() - 0.5) * 0.08,
        (Math.random() - 0.5) * 0.08
      ).normalize()
    );
  }

  // Field particles
  for (let i = 0; i < FIELD_COUNT; i++) {
    const pos = randomInEllipsoid();
    fieldPositions.push(pos);
    fieldPhases.push(Math.random() * Math.PI * 2);
    fieldDirections.push(
      new THREE.Vector3(
        (Math.random() - 0.5) * 0.08,
        (Math.random() - 0.5) * 0.08,
        (Math.random() - 0.5) * 0.08
      ).normalize()
    );
  }

  const icoGeometry = new THREE.IcosahedronGeometry(particleRadius, 0);

  // Core material (additive)
  const coreMaterial = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#ff2a38'),
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 0.5,
    transparent: true,
    opacity: 1,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide,
  });

  // Field material
  const fieldMaterial = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#e8ecf2'),
    emissive: new THREE.Color('#e8ecf2'),
    emissiveIntensity: 0.9,
    metalness: 0,
    roughness: 1,
    transparent: true,
    opacity: 1,
    blending: THREE.NormalBlending,
    depthWrite: true,
    side: THREE.DoubleSide,
  });

  const coreMesh = new THREE.InstancedMesh(icoGeometry, coreMaterial, CORE_COUNT);
  const fieldMesh = new THREE.InstancedMesh(icoGeometry, fieldMaterial, FIELD_COUNT);
  coreMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  fieldMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);

  const dummy = new THREE.Object3D();

  // Initialize matrices at core origin with scale 0 (for emerge animation)
  for (let i = 0; i < CORE_COUNT; i++) {
    dummy.position.set(0, 0, 0);
    dummy.scale.set(0, 0, 0);
    dummy.updateMatrix();
    coreMesh.setMatrixAt(i, dummy.matrix);
  }
  for (let i = 0; i < FIELD_COUNT; i++) {
    dummy.position.set(0, 0, 0);
    dummy.scale.set(0, 0, 0);
    dummy.updateMatrix();
    fieldMesh.setMatrixAt(i, dummy.matrix);
  }
  coreMesh.instanceMatrix.needsUpdate = true;
  fieldMesh.instanceMatrix.needsUpdate = true;

  group.add(coreMesh);
  group.add(fieldMesh);

  // Ambient light to give some base illumination
  const ambient = new THREE.AmbientLight(0xffffff, 0.2);
  group.add(ambient);

  // Helper for opacity based on depth
  function depthOpacity(z) {
    const clampedZ = THREE.MathUtils.clamp(z, -5, 0);
    const t = (0 - clampedZ) / 5; // 0 at z=0, 1 at z=-5
    return THREE.MathUtils.lerp(0.9, 0.15, t);
  }

  // Particle emerge animation via GSAP
  const emergeTweens = [];

  const maxCoreDist = coreRadius;
  const maxFieldDist = Math.sqrt(
    Math.pow(ellipsoidSize.x / 2, 2) +
      Math.pow(ellipsoidSize.y / 2, 2) +
      Math.pow(ellipsoidSize.z / 2, 2)
  );

  for (let i = 0; i < CORE_COUNT; i++) {
    const targetPos = corePositions[i];
    const distance = targetPos.length();
    const proxy = { p: 0 };
    const tween = gsap.to(proxy, {
      p: 1,
      duration: 1.4,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      delay: (distance / maxCoreDist) * 0.3,
      onUpdate: () => {
        dummy.position.copy(targetPos.clone().multiplyScalar(proxy.p));
        dummy.scale.setScalar(proxy.p);
        dummy.updateMatrix();
        coreMesh.setMatrixAt(i, dummy.matrix);
        coreMesh.instanceMatrix.needsUpdate = true;
      },
    });
    emergeTweens.push(tween);
  }

  for (let i = 0; i < FIELD_COUNT; i++) {
    const targetPos = fieldPositions[i];
    const distance = targetPos.clone().sub(ellipsoidCenter).length();
    const proxy = { p: 0 };
    const tween = gsap.to(proxy, {
      p: 1,
      duration: 1.4,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      delay: (distance / maxFieldDist) * 0.3,
      onUpdate: () => {
        dummy.position.copy(targetPos.clone().multiplyScalar(proxy.p));
        dummy.scale.setScalar(proxy.p);
        dummy.updateMatrix();
        fieldMesh.setMatrixAt(i, dummy.matrix);
        fieldMesh.instanceMatrix.needsUpdate = true;
      },
    });
    emergeTweens.push(tween);
  }

  // Drift and core pulse updates
  const startTime = performance.now();

  function updateDrift() {
    const elapsed = (performance.now() - startTime) / 1000; // seconds
    const driftFreq = 0.05; // Hz
    const pulseFreq = 0.1; // Hz

    // Core pulse
    coreMaterial.emissiveIntensity = 1.5 + 0.3 * Math.sin(2 * Math.PI * pulseFreq * elapsed);

    // Core particles drift
    for (let i = 0; i < CORE_COUNT; i++) {
      const dir = coreDirections[i];
      const phase = corePhases[i];
      const offset = dir.clone().multiplyScalar(0.04 * Math.sin(2 * Math.PI * driftFreq * elapsed + phase));
      dummy.matrix.fromArray(coreMesh.getMatrixAt(i));
      dummy.position.add(offset);
      dummy.updateMatrix();
      coreMesh.setMatrixAt(i, dummy.matrix);
    }

    // Field particles drift
    for (let i = 0; i < FIELD_COUNT; i++) {
      const dir = fieldDirections[i];
      const phase = fieldPhases[i];
      const offset = dir.clone().multiplyScalar(0.04 * Math.sin(2 * Math.PI * driftFreq * elapsed + phase));
      dummy.matrix.fromArray(fieldMesh.getMatrixAt(i));
      dummy.position.add(offset);
      dummy.updateMatrix();
      fieldMesh.setMatrixAt(i, dummy.matrix);
    }

    coreMesh.instanceMatrix.needsUpdate = true;
    fieldMesh.instanceMatrix.needsUpdate = true;
  }

  group.onBeforeRender = function () {
    updateDrift();
  };

  // Text rendering using font atlas
  const heroText = ctx.fontAtlas.createText('NOVA ATELIER', {
    atlasIndex: 0,
    region: { x: 0, y: 0, w: 512, h: 320 },
    fontSize: 124,
    color: '#e8ecf2',
    align: 'center',
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createText('Precision instruments for the dark hours.', {
    atlasIndex: 0,
    region: { x: 0, y: 0, w: 512, h: 320 },
    fontSize: 40,
    color: '#e8ecf2',
    align: 'center',
  });
  subheadText.position.set(0, -0.25, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createText('EST. 2019 / GENEVA AND KYOTO', {
    atlasIndex: 0,
    region: { x: 0, y: 0, w: 512, h: 320 },
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // Apply cinematic primitives from config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        ctx.primitives[prim.name](group, prim.params);
      }
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    // Dispose meshes
    coreMesh.geometry.dispose();
    coreMesh.material.dispose();
    fieldMesh.geometry.dispose();
    fieldMesh.material.dispose();

    // Dispose text meshes if they have geometries/materials
    [heroText, subheadText, captionText].forEach((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });

    // Kill tweens
    emergeTweens.forEach((t) => t.kill());

    // Remove onBeforeRender
    delete group.onBeforeRender;
  };

  group.userData.handlers = {};

  return group;
}
